s=open('/home/claude/bennys-town/index.html').read()
font=open('/tmp/build3/fontstyle.html').read()
s=s.replace('<link href="https://fonts.googleapis.com/css2?family=Poppins:wght@600;700;800&display=swap" rel="stylesheet">', font)
s=s.replace("const N = HOUSES.length;","const N = HOUSES.length;\nlet VIS = Infinity; const VIDEO = /video/.test(location.hash); let BENNY_O = null;",1)
s=s.replace("for (const h of HOUSES) { const [sx, sy] = uvS(h.i, h.j); if (sx < -150","for (const h of HOUSES) { if (h.idx >= VIS) continue; const [sx, sy] = uvS(h.i, h.j); if (sx < -150",1)
s=s.replace("ctx.globalAlpha = fade ? .3 : 1; ctx.drawImage(sp_.c, sx - sp_.ax * k, sy - sp_.ay * k, sp_.c.width * k, sp_.c.height * k);","ctx.globalAlpha = fade ? .3 : 1; const pk = VIDEO ? eBack(clamp((VIS - h.idx) / 45, 0, 1)) : 1; if (pk > .02) ctx.drawImage(sp_.c, sx - sp_.ax * k * pk, sy - sp_.ay * k * pk, sp_.c.width * k * pk, sp_.c.height * k * pk);")
s=s.replace("  for (let idx = N; idx < LOTS.length && LOTS[idx].d <= maxD; idx++) {","  for (let idx = Math.min(N, Math.ceil(VIS)); idx < LOTS.length && LOTS[idx].d <= maxD; idx++) {")
s=s.replace("if (idx < N + 40) objs.push({ d: L.i + L.j, f: () => drawSignPost(sx, sy, z) });","if (idx < (VIDEO ? N : N + 40)) objs.push({ d: L.i + L.j, f: () => drawSignPost(sx, sy, z) });")
s=s.replace("drawBenny(ctx, x, y + 4 * z, .25 * z, { pose: 'sit', mood: TOWN.bankCents > 0 ? 'hope' : 'sad', look: [0, .6], blink: (S.T % 3.7) < .12 });","drawBenny(ctx, x, y + 4 * z, .25 * z, Object.assign({ pose: 'sit', mood: TOWN.bankCents > 0 ? 'hope' : 'sad', look: [0, .6], blink: (S.T % 3.7) < .12 }, BENNY_O ? BENNY_O() : {}));")
s=s.replace("  // labels\n","  if (VIDEO) return;\n  // labels\n",1)
s=s.replace("window.SITE = { flyTo, search, HOUSES, open3D };", open('/tmp/build3/vid.js').read()+"\nwindow.SITE = { flyTo, search, HOUSES, open3D };")
s=s.replace("const go = () => start();","const go = () => { if (VIDEO) { const caps = __CAPS__, mouth = __MOUTH__; EP.init(caps, mouth); window.READY = true; return; } start(); };")
s=s.replace("__CAPS__",open('/tmp/build3/caps.json').read()).replace("__MOUTH__",open('/tmp/build3/mouth.json').read())
assert s.count('BENNY_O ? BENNY_O()')==1 and 'if (h.idx >= VIS)' in s and 'const pk = VIDEO' in s
open('/tmp/build3/build3.html','w').write(s)
